create table product_variants (id bigint not null auto_increment, parent_id bigint not null, product_id bigint not null, label varchar(100) not null, size varchar(50), color varchar(50), primary key(id), unique key uk_variant_product(product_id), index ix_variant_parent(parent_id)) engine=InnoDB;
create table stock_movements (id bigint not null auto_increment, product_id bigint not null, delta integer not null, resulting_quantity integer not null, reason varchar(40) not null, reference varchar(150), created_at datetime(6) not null, primary key(id), index ix_movement_product_time(product_id,created_at)) engine=InnoDB;
